const file_path="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/37.csv";
const content=await tools.Read({file_path});
if(typeof content!=="string") throw new Error("Expected CSV text");
const lines=content.trim().split("\n");
const rows=lines.slice(1).map((line,i)=>{const v=line.split(",");return {line:i+2,raw:line,truck:v[0],at:v[1],lat:Number(v[2]),lon:Number(v[3])};});
const radians=x=>x*Math.PI/180;
function distance(r){const a=Math.sin(radians(r.lat-30.1669)/2)**2+Math.cos(radians(30.1669))*Math.cos(radians(r.lat))*Math.sin(radians(r.lon+96.3977)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
const start=Date.parse("2026-08-20T20:56:02Z"), end=Date.parse("2026-08-20T21:16:02Z");
const nearby=rows.filter(r=>Date.parse(r.at)>=start&&Date.parse(r.at)<=end).map(r=>({...r,dist_m:distance(r)})).sort((a,b)=>a.dist_m-b.dist_m);
text({source:"telematics/37.csv",totalRows:rows.length,rowsInWindow:nearby.length,rowsWithin3000m:nearby.filter(r=>r.dist_m<3000),nearestInWindow:nearby.slice(0,5)});
